/* =========================================================
   Puff · 长夜＆机械之心 × 夜间纯黑极简机械（终极拔框版）
   ➠如果有灰雾，退出来重进就好了
   原因：软件自带的渲染引擎（WebView）卡了，没把透明图层刷新出来，退出重进相当于强制清空了缓存重新画，所以就正常了。
   ========================================================= */

/* 1. 强制全局方角 */
.off-app .off-list, .off-app .off-list-ava, .off-app.off-app-session .off-passage-sheet,
.off-app .off-compose-bar, .off-app .off-thinking-chip {
  border-radius: 0 !important;
}

/* 2. 背景图：黑色星空 */
.off-app, .off-app .off-stage, .off-app.off-app-session .off-stage, .off-app.off-app-session .off-stage.has-bg {
  background-color: #000000 !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141288ba.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}

/* =========================================================
   👇 全局文字强制纯白 + 强黑边护体
   ========================================================= */
.off-app, .off-app div, .off-app span, .off-app p, .off-app a, .off-app label, .off-app li, .off-app input, .off-app select {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  text-shadow: 0 1px 3px #000, 0 0 5px #000 !important; 
}

.off-app button, .off-app [class*="btn"], .off-app [class*="button"], .off-app .off-list-btn {
  background: rgba(0, 0, 0, 0.5) !important;
  border: 1px solid #444 !important;
  color: #ffffff !important; -webkit-text-fill-color: #ffffff !important;
  text-shadow: none !important;
}

/* =========================================================
   👇【终极扒皮】：全局绞杀所有顶栏返回键的底框！
   ========================================================= */
/* 针对所有可能的包裹层、按钮、图标、甚至是伪元素进行透明化 */
.off-app [class*="head"] > div:first-child,
.off-app [class*="head"] > a:first-child,
.off-app [class*="nav"] > div:first-child,
.off-app [class*="nav"] > a:first-child,
.off-app [class*="back"],
.off-app [class*="back"] *,
.off-app [class*="return"] {
  background: transparent !important; 
  background-color: transparent !important;
  border: none !important; 
  box-shadow: none !important;
  border-radius: 0 !important;
}

/* =========================================================
   3. 共处列表页（高透）
   ========================================================= */
.off-app:not(.off-app-session) .off-list {
  background: rgba(0, 0, 0, 0.2) !important; /* 极透 */
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
}

/* 👇 单聊/群共处做框（不受去框影响） */
.off-app:not(.off-app-session) .off-stage-head [class*="filter"],
.off-app:not(.off-app-session) .off-stage-head [class*="tab"],
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] {
  background: transparent !important; border: none !important;
}
.off-app:not(.off-app-session) .off-stage-head [class*="filter"] button,
.off-app:not(.off-app-session) .off-stage-head [class*="tab"] button,
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] button {
  background: rgba(0, 0, 0, 0.2) !important;
  border: 1px solid #333 !important; 
  color: #888888 !important; -webkit-text-fill-color: #888888 !important;
  text-shadow: none !important;
}
.off-app:not(.off-app-session) .off-stage-head [class*="filter"] button.on,
.off-app:not(.off-app-session) .off-stage-head [class*="tab"] button.on,
.off-app:not(.off-app-session) .off-stage-head [class*="switch"] button.on {
  background: rgba(0, 0, 0, 0.8) !important;
  border: 1px solid #ffffff !important; 
  color: #ffffff !important; -webkit-text-fill-color: #ffffff !important;
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.5) !important; 
}

/* =========================================================
   4. 聊天顶栏 + 白色心电图 + 白色爱心
   ========================================================= */
.off-app.off-app-session .off-stage-head {
  background: transparent !important; border-bottom: none !important;
  position: relative !important; overflow: visible !important; z-index: 10 !important;
}
.off-app.off-app-session .off-stage-head::after {
  content: "" !important; position: absolute !important;
  bottom: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow 3s linear infinite !important; z-index: 99 !important;
}
.off-app.off-app-session .off-stage-head::before {
  content: '♥' !important; position: absolute !important;
  bottom: -23px !important; left: 10% !important; font-size: 16px !important;
  color: #ffffff !important; text-shadow: 0 0 8px rgba(255, 255, 255, 0.9) !important; 
  z-index: 999 !important; pointer-events: none !important;
  animation: heart-walk 4s ease-in-out infinite alternate !important;
}

/* =========================================================
   5. 消息卡片与对话（极高透）
   ========================================================= */
.off-app.off-app-session .off-passage-sheet {
  background: rgba(0, 0, 0, 0.1) !important; /* 极透 */
  border: 1px solid rgba(255, 255, 255, 0.1) !important; 
  box-shadow: none !important;
}

.off-app.off-app-session .off-prose-dial,
.off-app.off-app-session [class*="dial"],
.off-app .off-compose-quote, .off-app .off-passage-quote, .off-app [class*="quote"] {
  display: inline !important; 
  box-decoration-break: clone !important; -webkit-box-decoration-break: clone !important;
  background: rgba(255, 255, 255, 0.05) !important; /* 极高透玻璃，只留微光 */
  border-radius: 0 !important; padding: 1px 8px !important; margin: 0 4px !important; 
  border: 1px solid rgba(255, 255, 255, 0.2) !important; 
  box-shadow: none !important; 
}

/* =========================================================
   6. 悬浮菜单与底栏（高透）
   ========================================================= */
.off-app [class*="menu"], .off-app [class*="popover"], .off-app [class*="popup"], .off-app [class*="dialog"] {
  background: rgba(10, 10, 10, 0.9) !important; /* 菜单保留高不透防看不清 */
  backdrop-filter: blur(24px) !important; border: 1px solid #333 !important;
  border-radius: 0 !important; box-shadow: 0 12px 36px rgba(0, 0, 0, 0.9) !important;
}
.off-app [class*="menu"] button, .off-app [class*="menu"] svg { fill: #ffffff !important; }
.off-app [class*="delete"] *, .off-app [class*="danger"] * { color: #ff4d4f !important; fill: #ff4d4f !important; }

.off-app.off-app-session .off-stage-dock {
  background: rgba(0, 0, 0, 0.2) !important; /* 极透底栏 */
  border-top: none !important;
  position: relative !important; overflow: visible !important; z-index: 10 !important; padding-top: 20px !important;
}
.off-app.off-app-session .off-stage-dock::before {
  content: "" !important; position: absolute !important;
  top: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow-reverse 3s linear infinite !important; z-index: 99 !important;
}

.off-app .off-compose-bar {
  background: rgba(0, 0, 0, 0.3) !important; /* 极透输入框 */
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
}
.off-app .off-compose-send, .off-app .off-compose-send * {
  color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; fill: #ffffff !important; background: transparent !important;
}

/* 7. 机械准星四角头像 */
.off-app .off-list-ava, .off-app .chat-ava-list {
  border-radius: 0 !important; border: 1px solid #333 !important; padding: 2px !important; background: #000 !important;
  background-image: 
    linear-gradient(#fff, #fff), linear-gradient(#fff, #fff),
    linear-gradient(#fff, #fff), linear-gradient(#fff, #fff),
    linear-gradient(#fff, #fff), linear-gradient(#fff, #fff),
    linear-gradient(#fff, #fff), linear-gradient(#fff, #fff) !important;
  background-size: 8px 2px, 2px 8px, 8px 2px, 2px 8px, 8px 2px, 2px 8px, 8px 2px, 2px 8px !important;
  background-position: top left, top left, top right, top right, bottom left, bottom left, bottom right, bottom right !important;
  background-repeat: no-repeat !important;
  box-shadow: inset 0 0 10px rgba(255,255,255,0.1) !important;
}
.off-app .off-list-ava img, .off-app .chat-ava-list img { border-radius: 0 !important; object-fit: cover !important; }

/* 动画 */
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes ecg-flow-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }
@keyframes heart-walk {
  0% { left: 4%; transform: translateY(0) scale(1); } 30% { transform: translateY(-4px) scale(1.15); } 
  60% { transform: translateY(0) scale(1); } 80% { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}
